{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "A 20% general warranty cap—AUD 4.8m—is not inherently unacceptable, but its adequacy depends on diligence, warranty coverage, recoverability and exclusions."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Lower thresholds and/or a tipping basket."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "24 months is a sensible opening request, subject to commercial negotiation."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject the proposal to apply general warranty limits “for administrative simplicity”."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Require express fraud and deliberate-concealment protections, with careful attribution drafting."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "No automatic disclosure of material merely “referred to” in other documents or discoverable through public searches."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no Buyer-knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require a Buyer-waivable condition precedent for effective written consent, satisfaction of associated conditions, and no materially adverse changes to the customer arrangement."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require an agreed payout letter, final settlement figure and repayment and effective security releases at Completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Agree express allocation to the Seller through payment, a price deduction or a properly defined debt-like/seller transaction-expense adjustment."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity covering losses from the ownership defect or associated claims—not merely reimbursement of the SOW3 payment"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity for the pre-Completion incident and resulting liabilities, investigation, remediation and notification costs, to the extent legally recoverable."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Negotiate consent rights or seller-funded treatment if these are exceptional or seller-driven commitments."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the blanket extension of clauses 9.3, 12.8 and 20.5 to every claim."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012’s share register is relevant evidence, not a complete title investigation."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not allow tax to disappear into the general warranty regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

